import json
from collections import Counter, defaultdict
d=json.load(open('graph.json'))
nodes={n['id']:n for n in d['nodes']}
callin=Counter()
callers=defaultdict(set)
for l in d['links']:
    if l.get('relation') in ('calls','indirect_call'):
        t=l['target']
        callin[t]+=1
        callers[t].add(l.get('source'))
def under_internal(nid):
    n=nodes.get(nid,{})
    sf=n.get('source_file','') or ''
    return sf.startswith('internal/')
rows=[]
for nid,c in callin.items():
    n=nodes.get(nid,{})
